89	    enum TaskType {
90	        ACTIVE("ACTIVE"),
91	
92	        STANDBY("STANDBY"),
93	
94	        GLOBAL("GLOBAL");
95	
96	        public final String name;
97	
98	        TaskType(final String name) {
99	            this.name = name;
100	        }
